using System;using System.Threading.Tasks;using System.Windows.Forms;using BeamScheduleFormatter;
class StoreUpdateGateTests {
 sealed class Fake:IStoreUpdateClient {public int Count;public bool Error,Installed;public Task<int> Check(IntPtr owner){if(Error)throw new Exception("offline");return Task.FromResult(Count);}public Task<bool> Install(){return Task.FromResult(Installed);}}
 static int checks;static void Check(bool value,string m){if(!value)throw new Exception(m);checks++;}
 [STAThread]static void Main(){Application.EnableVisualStyles();Check(!StoreUpdateGate.IsPackaged(),"ZIP/test process detected as packaged");using(var f=new StoreUpdateForm(new Fake{Count=0})){f.Check().GetAwaiter().GetResult();Check(f.DialogResult==DialogResult.OK,"Up-to-date launch blocked");}using(var f=new StoreUpdateForm(new Fake{Count=1})){f.Check().GetAwaiter().GetResult();Check(f.DialogResult!=DialogResult.OK,"Outdated version allowed");f.Install().GetAwaiter().GetResult();Check(f.DialogResult!=DialogResult.OK,"Cancelled install allowed tools");}using(var f=new StoreUpdateForm(new Fake{Count=1,Installed=true})){f.Check().GetAwaiter().GetResult();f.Install().GetAwaiter().GetResult();Check(f.DialogResult!=DialogResult.OK,"Old process allowed after successful update");}using(var f=new StoreUpdateForm(new Fake{Error=true})){f.Check().GetAwaiter().GetResult();Check(f.DialogResult!=DialogResult.OK,"Offline check allowed launch");}var retry=new Fake{Error=true};using(var f=new StoreUpdateForm(retry)){f.Check().GetAwaiter().GetResult();retry.Error=false;retry.Count=0;f.Check().GetAwaiter().GetResult();Check(f.DialogResult==DialogResult.OK,"Retry after network recovery blocked");}Console.WriteLine("PASS: "+checks+" Store gate cases: current/older version, cancelled/completed install, offline denial, retry and ZIP scope. Live retail Store update requires a Store-installed build.");}
}
